    "id" bigint generated by default as identity not null,
    "title" text not null,
    "url" text not null
);


alter table "library"."meditations" enable row level security;

create table "library"."resources" (
    "id" bigint generated by default as identity not null,
    "title" text not null,
    "url" text not null
);


alter table "library"."resources" enable row level security;

CREATE UNIQUE INDEX cache_pkey ON library.cache USING btree (type);

CREATE UNIQUE INDEX claire_prompts_pkey ON library.claire_prompts USING btree (id);

CREATE UNIQUE INDEX journal_prompts_pkey ON library.journal_prompts USING btree (id);

