CREATE UNIQUE INDEX resources_pkey ON library.resources USING btree (id);

alter table "library"."cache" add constraint "cache_pkey" PRIMARY KEY using index "cache_pkey";

alter table "library"."claire_prompts" add constraint "claire_prompts_pkey" PRIMARY KEY using index "claire_prompts_pkey";

alter table "library"."journal_prompts" add constraint "journal_prompts_pkey" PRIMARY KEY using index "journal_prompts_pkey";

